///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const urltaskdd = "&TASK_DD=" + edt_TASK_DD.getValue(); // 마감일

    let url;

    // 상장일자 가져오기 (TBLD_BZ_CALND 테이블사용)
    url += urltaskdd;
    const sbmOptions = {
        id : "sbm_dts_Get_ListDD",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_Get_ListDD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 마감이력가져오기
    url += urltaskdd;
    const sbmOptions2 = {
        id : "sbm_dts_Item",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // 마감처리 조회
        let url_new = "/listingCommon.do?method=listGeneral" + "&outputMessageId=DIGITAL_NEWLISTING_SEARCH_OUT" +
            // "&outputMessageId=DIGITAL_NEWLISTING_SEARCH_RV_OUT" +
            "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.digital.newlst.select.list.condition" + "&{P}param01=" + edt_LIST_DD.getValue();
        url_new += "&SCREN_ID=" + "ULDSTF70016.xml";
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_New_Proc.DataID = encodeURI(url_new);
        dts_New_Proc.Reset();
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        // 마감처리내역 조회
        url_new += "&SCREN_ID=" + "ULDSTF70016.xml";
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_New_Search",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_New_Search=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

// 재마감 버튼 클릭시 (현업관리자만 버튼보임)

/**
 * @method
 * @name recls
 * @description recls 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recls = async function() {
    scwin.procJob = "재마감처리";
    if (!await scwin.checkProcDt(scwin.procJob)) return;
    let res = window.confirm("재마감처리를 선택 하셨습니다.\n재마감처리는 이전마감처리기록을 삭제하므로\n재마감처리후 다시 마감처리를 하셔야 됩니다.\n\n재마감처리를 하시겠습니까?");
    if (res) {
        await scwin.trSetHeader();
        trs_Cls.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Cls",
            action : "/digital/DigitalListinvstg.do",
            ref : "dts_Cls",
            target : "trs_Cls=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name trSetHeader
 * @description CHRG_EMP_NO,LIST_DD 설정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trSetHeader = async function() {
    // CHRG_EMP_NO,LIST_DD 설정
    const sbmOptions = {
        id : "sbm_dts_Cls",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Cls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Cls.insertRow();
};

/**
 * @method
 * @name trsRevw
 * @description 담당자 확인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trsRevw = async function() {
    await scwin.trSetHeader();
    dts_Cls.setCellData(1, "CHRG_EMP_NO", js_emp_no);
    trs_revw.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_revw",
        action : "/digital/DigitalListinvstg.do",
        ref : "dts_Cls",
        target : "trs_revw=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name trs
 * @description 팀장승인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    await scwin.trSetHeader();
    dts_Cls.setCellData(1, "LIST_DD", edt_LIST_DD.getValue());
    dts_Cls.setCellData(1, "CHRG_EMP_NO", js_emp_no);
    trs_Cls.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Cls",
        action : "/digital/DigitalListinvstg.do",
        ref : "dts_Cls",
        target : "trs_Cls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name revw
 * @description 담당자 확인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revw = async function() {
    scwin.procJob = "담당자 확인";
    if (!await scwin.checkProcDt(scwin.procJob)) return;
    res = window.confirm("담당자 확인 하시겠습니까?");
    if (res) {
        await scwin.trsRevw();
    }
};

/**
 * @method
 * @name cls
 * @description 팀장승인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cls = async function() {
    if (txb_APPROV_TM.getValue() === "") {
        await $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return true;
    }
    scwin.procJob = "마감처리";
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }
    const commit = window.confirm("팀장 승인 하시겠습니까?");
    if (commit) {
        await scwin.trs();
    }
};

/**
 * @method
 * @name buttonSetDis
 * @description 담당자 승인, 팀장승인, 재마감처리
 * @returns {void}
 * @hidden N
 */
scwin.buttonSetDis = function() {
    // 담당자일때
    if (scwin.pJobTitl === "03") {
        if (txb_BZ_CLS_TM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else {
            if (txb_APPROV_EMP_NM.getValue() === "") {
                // 담당자확인을 않했을 경우
                btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
                btn_Revw.setDisabled(false);
            } else {
                btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
                btn_Revw.setDisabled(true);
            }
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        }
        //    showObj(btn_Recls, false);

    }
    // 팀장일때 - 마감처리
    else {
        if (txb_BZ_CLS_TM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else {
            if (txb_APPROV_EMP_NM.getValue() === "") {
                // 담당자확인을 안했을 경우
                btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
                btn_Revw.setDisabled(false);
                btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
                btn_Cls.setDisabled(true);
            } else {
                btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
                btn_Revw.setDisabled(true);
                btn_Cls.setBackgroundImage("../img/btn_BosApv.gif");
                btn_Cls.setDisabled(false);
            }
        }
        //    showObj(btn_Recls, false);

    }

    // 재마감 처리 버튼 - 시스템 관리자
    if (js_dep_cd === 'ZSYS') {
        btn_Recls.setBackgroundImage("../img/btn_ReCls.gif");
        btn_Recls.setDisabled(false);
        btn_Recls.show("");
    } else {
        btn_Recls.hide();
    }
};

