/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_New_Proc, {fileName: "신규상장 마감처리목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_New_ProcLog, {fileName: "신규상장 마감처리이력목록", type: "8"});
    }
};
